ON CONFLICT (codigo)
DO UPDATE SET

    nome =
        EXCLUDED.nome,

    sigla =
        EXCLUDED.sigla,

    cidade =
        EXCLUDED.cidade,

    estado =
        EXCLUDED.estado,

    codigo_organizacao_academica =
        EXCLUDED.codigo_organizacao_academica,

    organizacao_academica =
        EXCLUDED.organizacao_academica,

    codigo_categoria_administrativa =
        EXCLUDED.codigo_categoria_administrativa,

    categoria_administrativa =
        EXCLUDED.categoria_administrativa,

    ano_censo =
        EXCLUDED.ano_censo,

    origem_dados =
        'INEP',

    ativo =
        TRUE;

COMMIT;


-- =========================================================
-- CONFERÊNCIA
-- =========================================================

SELECT
    COUNT(*) AS total_ies
FROM universidade
WHERE origem_dados = 'INEP';


SELECT
    organizacao_academica,
    COUNT(*) AS quantidade
FROM universidade
WHERE origem_dados = 'INEP'
GROUP BY organizacao_academica
ORDER BY quantidade DESC;


-- Conferência do IFAL

SELECT
    codigo,
    nome,
    sigla,
    organizacao_academica,
    categoria_administrativa,
    cidade,
    estado

FROM universidade

WHERE
    UPPER(
        COALESCE(
            sigla,
            ''
        )
    ) = 'IFAL'

    OR

    UPPER(nome)
        LIKE '%INSTITUTO FEDERAL DE ALAGOAS%';
